[CmdletBinding()]param([string]$ProjectRoot=".",[Parameter(Mandatory=$true)][string[]]$FindingIds,[Parameter(Mandatory=$true)][string[]]$ScopePaths,[Parameter(Mandatory=$true)][string[]]$VerificationRequired,[switch]$Apply)
$ErrorActionPreference="Stop";$Root=(Resolve-Path $ProjectRoot).Path;$Agy=Join-Path $Root ".agy";$Wi=Get-Content (Join-Path $Agy "WORK_ITEM.json") -Raw|ConvertFrom-Json;$BudgetPath=Join-Path $Agy "REPAIR_BUDGET.json";$Used=0;if(Test-Path $BudgetPath){$Used=[int](Get-Content $BudgetPath -Raw|ConvertFrom-Json).repair_batches_used};$Batch="RB-{0:D3}"-f($Used+1);$Now=(Get-Date).ToUniversalTime().ToString("o")
$D=[ordered]@{schema_version="1.0.0";work_item_id=[string]$Wi.work_item_id;batch_id=$Batch;finding_ids=@($FindingIds|Select-Object -Unique);scope_paths=@($ScopePaths|Select-Object -Unique);verification_required=@($VerificationRequired|Select-Object -Unique);status="ready";generated_at_utc=$Now;notes=@("The owner brief remains immutable.")}
$Out=Join-Path $Agy "REPAIR_DELTA.json";if($Apply){[IO.File]::WriteAllText($Out,($D|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Write-Host "Repair delta published: $Batch"}else{$D|ConvertTo-Json -Depth 20}
